        try {
            InetAddress inetAddress = InetAddress.getByName(host);
            String ip = inetAddress.getHostAddress();

            // Check if resolved IP is in blocked ranges
            if (isIpBlocked(ip)) {
                throw new SecurityException("Access to this IP address is forbidden");
            }

